    if (Math.abs(yX - position.y) <= .34 && !blockedAt(house, tryX, position.z, yX)) { position.x = tryX; position.y = yX; }
    const tryZ = position.z + sz, yZ = floorHeightAt(house, position.x, tryZ, position.y);
    if (Math.abs(yZ - position.y) <= .34 && !blockedAt(house, position.x, tryZ, yZ)) { position.z = tryZ; position.y = yZ; }
    const support = floorHeightAt(house, position.x, position.z, position.y);
    if (Number.isFinite(support) && Math.abs(support-position.y) <= .34) position.y = support;
